import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('rename_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
const refs={track:'track:track-1',scene:'scene:scene-1',clip:'clip:clip-1',device:'device:utility-1',locator:'locator:locator-1',takeLane:'take-lane:track-1:0'};
function row(sim,kind){const s=sim.state;return kind==='track'?s.tracks[0]:kind==='scene'?s.scenes[0]:kind==='clip'?s.tracks[0].clips[0]:kind==='device'?s.tracks[0].devices[0]:kind==='locator'?s.arrangement.locators[0]:s.tracks[0].takeLanes[0];}
const rows=[];for(const tool of ['liveObjectRenamePreviewAsync','liveObjectRenameApplyAsync'])for(const kind of (tool.includes('Preview')?Object.keys(refs):['track'])){const valid=tool.includes('Preview')?{kind,ref:refs[kind],name:'New Name'}:{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of Object.keys(valid)){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,0,'','x','a'.repeat(257)])cases.push({...valid,[key]:value});}for(const args of cases){const host=new McpHost(new DeterministicLiveSimulator());let result;try{result=clean(await host[tool](1,args));}catch(e){result={error:e.message};}rows.push({tool,args,result});}}
const workflows=[];
for(const kind of Object.keys(refs))for(const scenario of ['normal','expire','epoch','name-edit','identity-edit','same-name','missing-identity','apply-before','apply-after','apply-cancel','apply-refusal','apply-no-effect','apply-read','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-other-name','undo-prior-name','undo-other-identity',...(kind==='track'?['return-prefix','return-prefixed']:[])]){
const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();let fault='',fired=false,afterInvoke=false;const original=row(sim,kind).name;if(scenario.startsWith('return-'))Object.assign(row(sim,kind),{kind:'return',name:'A-Reverb'});if(scenario==='missing-identity')delete row(sim,kind).objectIdentity;
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure');}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);if(!fired&&['before','cancel','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error(fault.endsWith('cancel')?'operation cancelled before dispatch':'injected operation failure');}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,result);afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}return result;}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
const host=new McpHost(adapter),results=[],states=[];const name=scenario==='same-name'?original:scenario==='return-prefixed'?'A-Delay':'New Name';const preview=await host.liveObjectRenamePreviewAsync(1,{kind,ref:refs[kind],name});results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
if(txid){const record=host.clipLifecycleTransactions.get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action,idempotencyKey:key};results.push(clean(action==='apply'?await host.liveObjectRenameApplyAsync(results.length+1,args):await host.liveUndoAsync(results.length+1,args)));states.push(clean(record));}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='name-edit')row(sim,kind).name='Manual';if(scenario==='identity-edit')row(sim,kind).objectIdentity='other';if(scenario.startsWith('apply-'))fault=scenario;
for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;
if(scenario==='undo-other-name')row(sim,kind).name='Manual';if(scenario==='undo-prior-name')row(sim,kind).name=original;if(scenario==='undo-other-identity')row(sim,kind).objectIdentity='other';if(scenario.startsWith('undo-')&&!['undo-other-name','undo-prior-name','undo-other-identity'].includes(scenario))fault=scenario;
for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key');}
workflows.push({kind,scenario,results,states,calls,target:row(sim,kind)});}
fs.writeFileSync(new URL('host-rename-oracle.json',import.meta.url),JSON.stringify({rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
